class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def square_free_part(n):
            res = 1
            i = 2
            while i * i <= n:
                if n % i == 0:
                    count = 0
                    while n % i == 0:
                        n //= i
                        count += 1
                    if count % 2 == 1:
                        res *= i
                i += 1
            if n > 1:
                res *= n
            return res

        groups = defaultdict(int)
        for num in nums:
            sf = square_free_part(num)
            groups[sf] += num

        return max(groups.values())
