class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def square_free(x):
            res = 1
            i = 2
            while i * i <= x:
                count = 0
                while x % i == 0:
                    count += 1
                    x //= i
                if count % 2 == 1:
                    res *= i
                i += 1
            if x > 1:
                res *= x
            return res

        groups = defaultdict(int)
        max_single = 0
        for num in nums:
            sf = square_free(num)
            groups[sf] += num
            if num > max_single:
                max_single = num

        max_sum = max_single
        for key in groups:
            if groups[key] > max_sum:
                max_sum = groups[key]

        return max_sum

