            letters_to_add.extend([chr(ord('a') + i)] * added[i])
        letters_to_add.sort()

        # Replace '?' in the original string with the sorted letters
        res = list(s)
        ptr = 0
        for i in range(len(res)):
            if res[i] == '?':
                res[i] = letters_to_add[ptr]
