class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7

        max_c = len(s)
        memo_steps = {}

        def compute_steps(c):
            if c in memo_steps:
                return memo_steps[c]
            if c == 1:
                memo_steps[c] = 0
                return 0
            bits = bin(c).count('1')
            res = 1 + compute_steps(bits)
            memo_steps[c] = res
            return res

        def count_numbers_less_than_s(s_str, c):
            m = len(s_str)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, count, tight):
                if pos == m:
                    return 1 if (count == c) and (not tight) else 0
                limit = int(s_str[pos]) if tight else 1
                total = 0
                for bit in [0, 1]:
                    if bit > limit:
                        continue
                    new_tight = tight and (bit == limit)
                    new_count = count + (bit == 1)
                    if new_count > c:
                        continue
                    total += dp(pos + 1, new_count, new_tight)
                return total

            return dp(0, 0, True)

        total = 0
        for c in range(1, max_c + 1):
            steps_c = compute_steps(c)
            if steps_c <= k - 1:
                cnt = count_numbers_less_than_s(s, c)
                total += cnt

        return total % MOD

