class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adj = defaultdict(list)
        for u, v, l in edges:
            adj[u].append((v, l))
            adj[v].append((u, l))

        max_len = [0]
        min_nodes = [float('inf')]

        def dfs(node, parent, value_count, current_sum, current_count):
            # Update the maximum length and minimum nodes
            if current_sum > max_len[0]:
                max_len[0] = current_sum
                min_nodes[0] = current_count
            elif current_sum == max_len[0]:
                if current_count < min_nodes[0]:
                    min_nodes[0] = current_count

            # Process children
            for child, length in adj[node]:
                if child == parent:
                    continue
                # Check if the child's value is not in the current path
                if value_count.get(nums[child], 0) == 0:
                    # Add the child's value to the count
                    value_count[nums[child]] = value_count.get(nums[child], 0) + 1
                    dfs(child, node, value_count, current_sum + length, current_count + 1)
                    # Backtrack
                    value_count[nums[child]] -= 1
                    if value_count[nums[child]] == 0:
                        del value_count[nums[child]]

        # For each node, start DFS with initial value count
        for i in range(n):
            initial_value_count = defaultdict(int)
            initial_value_count[nums[i]] = 1
            dfs(i, -1, initial_value_count, 0, 1)

        return [max_len[0], min_nodes[0]]

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        from collections import defaultdict

        # Build the adjacency list
        adj = [[] for _ in range(n)]
        for u, v, length in edges:
            adj[u].append((v, length))
            adj[v].append((u, length))

        result = [0, 1]  # [max_length, min_nodes]

        def dfs(node, parent, current_set):
            # Check if current node's value is in current_set
            if nums[node] in current_set:
                return (0, 1)
            current_set.add(nums[node])
            max_len = 0
            min_nodes = 1
            for child, length in adj[node]:
                if child != parent:
                    if nums[child] not in current_set:
                        child_max_len, child_min_nodes = dfs(child, node, current_set)
                        new_len = child_max_len + length
                        new_nodes = child_min_nodes + 1
                        if new_len > max_len:
                            max_len = new_len
                            min_nodes = new_nodes
                        elif new_len == max_len:
                            min_nodes = min(min_nodes, new_nodes)
            current_set.remove(nums[node])
            # Update the result
            if max_len > result[0]:
                result[0] = max_len
                result[1] = min_nodes
            elif max_len == result[0]:
                result[1] = min(result[1], min_nodes)
            return (max_len, min_nodes)

        # Start DFS from root (0) with empty set
        dfs(0, -1, set())
        return result

