    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        # Precompute the sets for each property list
        sets = [set(arr) for arr in properties]

        # Process all pairs of nodes to check for edges
        for i in range(n):
            for j in range(i + 1, n):
                common = len(sets[i] & sets[j])
                if common >= k:
                    union(i, j)

        # Count the number of unique roots
        roots = set()
        for x in range(n):
            roots.add(find(x))

        return len(roots)
